// Also search for typeless CDN patterns
let cdnMatches = html.match(/https?:\/\/[^"'\s<>]*(typeless|cdn)[^"'\s<>]*/gi) || [];
found = found.concat(cdnMatches.slice(0, 10));
found

// Override window.location setter and anchor click to intercept download
let downloadUrl = null;
const origCreateElement = document.createElement.bind(document);
document.createElement = function(tag) {
  const el = origCreateElement(tag);
  if (tag.toLowerCase() === 'a') {
    const origClick = el.click.bind(el);
    el.click = function() {
      if (el.href && el.href.includes('download') || el.download) {
        downloadUrl = el.href;
        window.__downloadUrl = el.href;
      }
      return origClick();
    };
  }
  return el;
};

// Also watch for fetch calls to get download URL
const origFetch = window.fetch;
window.fetch = async function(...args) {
  const url = typeof args[0] === 'string' ? args[0] : args[0]?.url;
  window.__lastFetchUrl = url;
  const res = await origFetch.apply(this, args);
  return res;
};

// Click the macOS download button
let btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim().includes('macOS'));
btn && btn.click();
